package truth

import "testing"

const count = "We ship 129 free plugins.\n"

// TestExemptionsPass: the same text that fails outside passes inside a
// generated region, a JSX expression, after a reasoned exempt comment, or in a
// file that says GENERATED BY.
func TestExemptionsPass(t *testing.T) {
	got := claimFindings(t, map[string]string{
		"bad.md":    count,
		"region.md": "<!-- BEGIN GENERATED:facts -->\n" + count + "<!-- END GENERATED:facts -->\n",
		"exempt.md": "<!-- truth: exempt a quoted marketing line from 2019 -->\n" + count + count,
		"gen.md":    "# T\n<!-- GENERATED BY tools/facts; DO NOT HAND EDIT -->\n" + count,
		"late.md":   "a\nb\nc\nGENERATED BY x\n" + count,
		"page.astro": "---\nconst n = 129; // 129 plugins\n---\n<p>{`129 free plugins`}</p>\n<p>129 free plugins</p>\n" +
			"<script>\nlet s = '129 plugins'\n</script>\n<style>\n/* 129 plugins */\n</style>\n",
		"page.mdx":    "Text {x ? '129 free plugins' : ''} and 129 free plugins\n{\n  `129 plugins`\n}\n",
		"fence.mdx":   "```json\n{ \"a\": \"129 plugins\" }\n```\n129 plugins\n",
		"plain.md":    "{129 free plugins}\n",
		"unclosed.md": "<!-- BEGIN GENERATED:facts -->\n" + count,
		"other.md":    "<!-- BEGIN GENERATED:a -->\n<!-- END GENERATED:b -->\n" + count,
	})
	wantFindings(t, got,
		"claims.counts bad.md:1",
		"claims.counts exempt.md:3",
		"claims.counts late.md:5",
		"claims.counts page.astro:5",
		"claims.counts page.mdx:1",
		"claims.counts fence.mdx:2",
		"claims.counts fence.mdx:4",
		"claims.counts plain.md:1",
		"claims.counts unclosed.md:2",
		"claims.counts other.md:3",
	)
}

// TestExemptWithoutReasonIsAFinding: the comment itself is a finding, and it
// exempts nothing.
func TestExemptWithoutReasonIsAFinding(t *testing.T) {
	got := claimFindings(t, map[string]string{
		"a.md": "<!-- truth: exempt -->\n" + count,
		"b.md": "<!-- truth: exempt   -->\n" + count,
		"c.md": "<!-- truth: exempt -->\nnothing here\n",
		"d.go": "// <!-- truth: exempt -->\n",
		"e.md": "<!-- truth: exempt because the page quotes a customer -->\nnothing here\n",
	})
	wantFindings(t, got,
		"truth.exempt-without-reason a.md:1", "claims.counts a.md:2",
		"truth.exempt-without-reason b.md:1", "claims.counts b.md:2",
		"truth.exempt-without-reason c.md:1")
}

// TestRegionsOptInForVocabulary: retired-term and banned-literal rules honour
// the markers only when they say exempt_regions: true (the claims.yaml
// vocabulary rules do; org.yaml rules do not).
func TestRegionsOptInForVocabulary(t *testing.T) {
	line := "Buy the " + proPlugins() + " now\n"
	got := claimFindings(t, map[string]string{
		"a.md": line,
		"b.md": "<!-- BEGIN GENERATED:x -->\n" + line + "<!-- END GENERATED:x -->\n",
		"c.md": "<!-- truth: exempt historic quote from the 2024 launch post -->\n" + line,
	})
	wantFindings(t, got, "vocab.pro-plugin a.md:1")
	org := "version: 1\nrules:\n  - {id: r, kind: retired-term, term: Old Name, message: m}\n"
	got = findingsOf(t, map[string]string{"org.yaml": org, "b.md": "<!-- BEGIN GENERATED:x -->\nOld Name\n<!-- END GENERATED:x -->\n"}, "org.yaml")
	wantFindings(t, got, "r b.md:2")
}

func TestMaskUnit(t *testing.T) {
	m := analyze("x.mdx", []string{"a {b} c", "{", "d", "}", "{open", "e"})
	for _, tc := range []struct {
		line, s, e int
		want       bool
	}{{0, 2, 5, true}, {0, 0, 1, false}, {2, 0, 1, true}, {5, 0, 1, false}, {4, 0, 2, false}} {
		if got := m.exempt(tc.line, tc.s, tc.e); got != tc.want {
			t.Errorf("exempt(%d,%d,%d) = %v", tc.line, tc.s, tc.e, got)
		}
	}
}
